package com.tradequest.app.core.simulation.path

/** One minute, in milliseconds. The path model's time unit. */
const val CANDLE_DURATION_MS: Long = 60_000L

/**
 * Version of the intraminute path model (Step 4.7).
 *
 * Bump [CURRENT] whenever anything that changes the *shape* of a generated path
 * changes: the waypoint ordering, the waypoint timing, or the rounding rule.
 * The version is part of [PathIdentity], so a path generated by one model is
 * never mistaken for a path generated by another.
 */
object PathModelVersion {
    /** The model described by `docs/adr-0002-intraminute-path.md`. */
    const val CURRENT: Int = 1
}

/**
 * One point the price is known to pass through, at [elapsedMs] into the minute.
 *
 * [elapsedMs] is measured from the start of the candle, so `0` is the open and
 * [CANDLE_DURATION_MS] is the close.
 */
data class PathWaypoint(
    val elapsedMs: Int,
    val priceUnits: Int,
)

/**
 * The candle as it looks partway through its own minute (Step 4.4).
 *
 * Every field is derived only from price movement that has already been
 * traversed. [highUnits] and [lowUnits] are the extremes *so far*, not the
 * completed candle's extremes, so a caller cannot learn the rest of the minute
 * early (product rule 2.2, "never reveal future historical prices").
 *
 * There is deliberately no volume field. The stored `tickVolume` is a total for
 * the whole minute, so exposing it here would leak the future. Volume becomes
 * known only when the candle completes.
 */
data class FormingCandle(
    val timestampUtcMs: Long,
    val openUnits: Int,
    val highUnits: Int,
    val lowUnits: Int,
    val closeUnits: Int,
    /** How far into the minute this reading is. `CANDLE_DURATION_MS` when complete. */
    val elapsedMs: Int,
) {
    val isComplete: Boolean get() = elapsedMs >= CANDLE_DURATION_MS.toInt()
}

/** Why a period has no path (Step 4.6). */
enum class GapReason {
    /** Minutes are absent from the dataset with no closure explanation. */
    MISSING_MINUTES,

    /** The market was genuinely closed, for example a weekend. */
    MARKET_CLOSURE,
}

/**
 * An explicit discontinuity between two candles (Step 4.6).
 *
 * The path engine never interpolates across candles, so a break between them is
 * a first-class value rather than something the chart is left to guess. A chart
 * draws no line across a [MarketGap]; execution must not treat the jump as
 * tradable movement, because no tradable movement exists there.
 *
 * [fromPriceUnits] is the previous candle's close and [toPriceUnits] the next
 * candle's open. They differ in general, which is exactly why the jump cannot
 * be interpolated: there is no information about how the price moved between
 * them, and inventing a path would fabricate market data (product rule 4.5).
 */
data class MarketGap(
    val fromUtcMs: Long,
    val toUtcMs: Long,
    val fromPriceUnits: Int,
    val toPriceUnits: Int,
    val reason: GapReason,
) {
    val durationMs: Long get() = toUtcMs - fromUtcMs
    val priceDeltaUnits: Int get() = toPriceUnits - fromPriceUnits
}

/**
 * Everything a generated path depends on (Step 4.7).
 *
 * The path is a pure function of this value. Two identities that are equal
 * produce identical paths; two that differ may not.
 *
 * Note the division of responsibility: the path *shape* depends only on the
 * OHLC and [pathModelVersion]. [datasetId] and [timestampUtcMs] are included so
 * that the same OHLC in two different datasets, or at two different minutes,
 * yields a distinct identity — they scope the path, they do not shape it.
 */
data class PathIdentity(
    val datasetId: String,
    val timestampUtcMs: Long,
    val openUnits: Int,
    val highUnits: Int,
    val lowUnits: Int,
    val closeUnits: Int,
    val pathModelVersion: Int = PathModelVersion.CURRENT,
) {
    /** Stable 64-bit fingerprint, for caching and for assertions in tests. */
    val fingerprint: Long
        get() = PathFingerprint.of(this)
}

/**
 * A stable, platform-independent hash of a [PathIdentity].
 *
 * FNV-1a, chosen because it is a fixed published algorithm with no reliance on
 * `hashCode()`, which is only *contractually* stable per type and easy to break
 * accidentally by reordering fields. The dataset id is folded as UTF-8 bytes so
 * its contribution does not depend on the JVM's string hashing either.
 */
object PathFingerprint {

    private const val FNV_OFFSET_BASIS: Long = -3750763034362895579L // 0xcbf29ce484222325
    private const val FNV_PRIME: Long = 1099511628211L               // 0x100000001b3

    fun of(identity: PathIdentity): Long {
        var hash = FNV_OFFSET_BASIS
        hash = foldBytes(hash, identity.datasetId.toByteArray(Charsets.UTF_8))
        hash = foldLong(hash, identity.timestampUtcMs)
        hash = foldLong(hash, identity.openUnits.toLong())
        hash = foldLong(hash, identity.highUnits.toLong())
        hash = foldLong(hash, identity.lowUnits.toLong())
        hash = foldLong(hash, identity.closeUnits.toLong())
        hash = foldLong(hash, identity.pathModelVersion.toLong())
        return hash
    }

    private fun foldBytes(seed: Long, bytes: ByteArray): Long {
        var hash = seed
        for (byte in bytes) {
            hash = (hash xor (byte.toLong() and 0xFFL)) * FNV_PRIME
        }
        return hash
    }

    private fun foldLong(seed: Long, value: Long): Long {
        var hash = seed
        var remaining = value
        repeat(Long.SIZE_BYTES) {
            hash = (hash xor (remaining and 0xFFL)) * FNV_PRIME
            remaining = remaining ushr 8
        }
        return hash
    }
}
